from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    s = paren_string.replace(" ", "")
    result = []
    balance = 0
    current = ""
    for char in s:
        if char == "(":
            balance += 1
        elif char == ")":
            balance -= 1
        current += char
        if balance == 0:
            result.append(current)
            current = ""
    return result
